@page "/categories"
@page "/categories/{CategoryName}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(CategoryName is not null ? $"{CategoryName} Recipes" : "All Categories")</PageTitle>

@if (CategoryName is null)
{
    <h1>All Categories</h1>
    <div class="list-group">
        @foreach (var category in RecipeService.GetCategories())
        {
            <a href="categories/@category" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                <span class="fw-bold">@category</span>
                <span class="badge bg-primary rounded-pill">@RecipeService.GetByCategory(category).Count</span>
            </a>
        }
    </div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    var recipes = RecipeService.GetByCategory(CategoryName);
    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category yet.</div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">@recipe.Description</p>
                            <div class="mb-2">
                                <span class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                    }
                                </span>
                                <small class="text-muted">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</small>
                            </div>
                            <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@_recipe.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item"><a href="categories/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead text-muted">@_recipe.Description</p>

    <div class="mb-4">
        <StarRating RecipeId="@_recipe.Id" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header fw-bold">🥘 Ingredients</div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in _recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-header fw-bold">📝 Steps</div>
                <div class="card-body">
                    <ol>
                        @foreach (var step in _recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span role="button"
              class="fs-4 @(star <= _hoveredStar ? "text-warning" : (star <= (int)Math.Round(_currentRating) ? "text-warning" : "text-secondary"))"
              style="cursor: pointer;"
              @onmouseover="() => _hoveredStar = star"
              @onmouseout="() => _hoveredStar = 0"
              @onclick="() => SubmitRating(star)">
            @(star <= (_hoveredStar > 0 ? _hoveredStar : (int)Math.Round(_currentRating)) ? "★" : "☆")
        </span>
    }
    <span class="ms-2 text-muted small">
        @if (_userRated)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        @_currentRating / 5 (@_ratingCount ratings)
    </span>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _hoveredStar;
    private bool _userRated;
    private double _currentRating;
    private int _ratingCount;

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            _currentRating = recipe.AverageRating;
            _ratingCount = recipe.RatingCount;
        }
    }

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        _userRated = true;
        LoadRating();
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit Your Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@_submission.Title</strong>" has been added to the <strong>@_submission.Category</strong> category.</p>
        <a href="categories/@_submission.Category" class="btn btn-primary">View Category</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_submission.Category">
                <option value="">-- Select a Category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="_submission.Ingredients"
                           placeholder="Enter one ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <div class="form-text">Enter one ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Preparation Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_submission.Steps"
                           placeholder="Enter one step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-success"
                disabled="@(string.IsNullOrWhiteSpace(_submission.Title) || string.IsNullOrWhiteSpace(_submission.Category) || string.IsNullOrWhiteSpace(_submission.Ingredients) || string.IsNullOrWhiteSpace(_submission.Steps))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeSubmission _submission = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_submission.Title) ||
            string.IsNullOrWhiteSpace(_submission.Category) ||
            string.IsNullOrWhiteSpace(_submission.Ingredients) ||
            string.IsNullOrWhiteSpace(_submission.Steps))
            return;

        RecipeService.AddRecipe(_submission);
        _submitted = true;
    }

    private void ResetForm()
    {
        _submission = new RecipeSubmission();
        _submitted = false;
    }
}

